    def _role(self, request: Request) -> str:
        session = request.cookies.get("session", "anon")
        return session if session in {"owner", "member"} else "anon"

    @staticmethod
    def _url(request: Request, path: str) -> str:
        return f"{request.mount}{path}?lang={request.lang}&amp;theme={request.theme}"

    def _style(self, theme: str) -> str:
        light = "--bg:#f4f7f8;--ink:#172133;--card:#ffffff;--wash:#e6f2f3;--accent:#08727b;--muted:#536274;--line:#ccd8dd;--subtle:#f7fafb"
