    def _page(self, request: Request, content: str, page: str) -> Response:
        w, role = self._words[request.lang], self._role(request)
        explicit_theme = request.query.get("theme") or request.cookies.get("theme")
        theme = explicit_theme if explicit_theme in ("light", "dark") else "system"
        links = (("/", "home"), ("/users", "users"), ("/reports", "reports"), ("/exports", "exports"), ("/legacy", "legacy"))
        nav = "".join(f'<a class="{"active" if path == request.path else ""}" href="{self._url(request, path)}"><span class="nav-index">0{index}</span>{escape(w[key])}</a>' for index, (path, key) in enumerate(links, 1))
        session = (f'<a class="account-link" href="{self._url(request, "/login")}">{escape(w["sign_in"])}</a>' if role == "anon" else f'<a class="account-link" href="{self._url(request, "/logout")}">{escape(w["sign_out"])}</a>')
        markup = f'''<!doctype html><html lang="{request.lang}" dir="{"rtl" if request.lang == "ar" else "ltr"}" data-theme="{theme}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark">{self._style(request.theme)}<title>{escape(w[page])} · {escape(w["brand"])}</title></head><body><div class="shell"><aside class="sidebar"><div class="sidebar-top"><div class="identity"><span class="mark">N</span><span>{escape(w["brand"])}<span class="product">{escape(w["product"])}</span></span></div></div><nav class="nav" aria-label="{escape(w["product"])}">{nav}</nav><div class="side-bottom"><div class="role-box"><span class="role-label">{escape(w["role"])}</span><span class="role-value">{escape(w[role])}</span></div>{session}</div></aside><div class="content"><header class="topbar"><span class="crumb">{escape(w["product"])} / {escape(w[page])}</span><div class="account"><span class="account-name">{escape(w["role"])}: {escape(w[role])}</span><span class="avatar">{role[:2].upper()}</span></div></header><main>{content}</main><footer>{escape(w["footer"])}</footer></div></div></body></html>'''
        return Response.html(markup)

    def _login(self, request: Request) -> Response:
        w = self._words[request.lang]
        error = ""
        if request.method == "POST":
            values = parse_qs(request.body.decode("utf-8", "replace"))
            account, password = values.get("username", [""])[0], values.get("password", [""])[0]
            if (account, password) in {("owner", "owner-pass"), ("member", "member-pass")}:
                return Response.redirect(f"{request.mount}/", **{"Set-Cookie": f"session={account}; Path=/; HttpOnly; SameSite=Lax"})
            error = f'<p class="notice" role="alert">{escape(w["bad_login"])}</p>'
        content = f'<section><p class="eyebrow">{escape(w["sign_in"])}</p><h1>{escape(w["login_title"])}</h1><p class="lede">{escape(w["login_copy"])}</p>{error}<form method="post" action="{self._url(request, "/login")}"><label>{escape(w["username"])}<input name="username" type="text" autocomplete="username" required="required"></label><label>{escape(w["password"])}<input name="password" type="password" autocomplete="current-password" required="required"></label><button class="tap primary" type="submit">{escape(w["submit"])}</button></form></section>'
        return self._page(request, content, "sign_in")

    blurb = "An operations console. Privilege inversion and a locale-only dead link."
    entry = "/reports"

    def handle(self, request: Request) -> Response:
        w, role = self._words[request.lang], self._role(request)
        if request.path == "/login":
            return self._login(request)
        if request.path == "/logout":
            if role == "anon":
                return Response.redirect(f"{request.mount}/login")
            return Response.redirect(f"{request.mount}/", **{"Set-Cookie": "session=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax"})
        if request.path == "/legacy":
            return Response.not_found()
        if request.path == "/":
            return self._page(request, self._dashboard(w, role, request), "home")
        if request.path == "/users":
            if role == "anon":
                return Response.redirect(f"{request.mount}/login")
            return self._page(request, self._users(w), "users")
        if request.path == "/reports":
            # Intentionally backwards: a lower privilege is the only one admitted.
            if role != "member":
                return Response.redirect(f"{request.mount}/login")
            return self._page(request, self._reports(w), "reports")
        if request.path == "/exports":
            # Intentionally hard-coded to the English route resolution.
            if request.lang != "en":
                return Response.not_found()
            if role == "anon":
                return Response.redirect(f"{request.mount}/login")
            return self._page(request, self._exports(w), "exports")
        return Response.not_found()

    @staticmethod
    def _dashboard(w: dict[str, str], role: str, request: Request) -> str:
        metrics = ((w["active"], "24", w["delta_seats"], ""), (w["deployments"], "18", w["delta_deployments"], ""), (w["alerts"], "3", w["delta_alerts"], " urgent"))
        cards = "".join(f'<article class="panel metric"><span class="eyebrow">{escape(label)}</span><strong>{number}</strong><span class="delta{kind}">{escape(delta)}</span></article>' for label, number, delta, kind in metrics)
        return f'<section class="page-head"><div><p class="eyebrow">{escape(w["overview_kicker"])}</p><h1>{escape(w["welcome"])}</h1><p class="lede">{escape(w["intro"])}</p></div><span class="badge neutral">{escape(w[role])}</span></section><section class="metrics" aria-label="{escape(w["activity"])}">{cards}</section><section class="dashboard-grid"><article class="panel"><div class="panel-head"><h2>{escape(w["events"])}</h2><a class="text-link" href="{AdminSite._url(request, '/') }#activity">{escape(w["view_all"])}</a></div><ul class="event-list" id="activity"><li><span class="dot"></span><span>{escape(w["security_review"])}</span><span class="event-time">14:20</span></li><li><span class="dot"></span><span>{escape(w["deploy_complete"])}</span><span class="event-time">12:48</span></li><li><span class="dot"></span><span>{escape(w["token_rotated"])}</span><span class="event-time">09:15</span></li><li><span class="dot"></span><span>{escape(w["access_requested"])}</span><span class="event-time">08:42</span></li></ul></article><aside class="panel"><div class="panel-head"><h2>{escape(w["status_panel"])}</h2><span class="badge">{escape(w["new"])}</span></div><div class="status-body"><p class="operational"><span class="dot"></span>{escape(w["all_systems"])}</p><p class="status-copy">{escape(w["status_copy"])}</p><div class="status-stats"><span class="status-stat">{escape(w["uptime"])}<strong>99.98%</strong></span><span class="status-stat">{escape(w["response"])}<strong>184 ms</strong></span></div></div></aside></section>'

    @staticmethod
    def _users(w: dict[str, str]) -> str:
        people = (("AM", "Ada Mensah", "ada@northstar.test", "owner", "14:20", "active_status"), ("SN", "Samira Noor", "samira@northstar.test", "member", "11:04", "active_status"), ("RP", "Rina Patel", "rina@northstar.test", "member", "16:42", "invited"), ("JL", "Jon Lee", "jon@northstar.test", "member", "3 days", "suspended")) if w["brand"] == "Northstar" else (("أم", "آدا منصور", "ada@northstar.test", "owner", "14:20", "active_status"), ("سن", "سميرة نور", "samira@northstar.test", "member", "11:04", "active_status"), ("رب", "رينا باتل", "rina@northstar.test", "member", "16:42", "invited"), ("جل", "جون لي", "jon@northstar.test", "member", "3 أيام", "suspended"))
        rows = "".join(f'<tr><td data-label="{escape(w["person"])}"><span class="person"><span class="avatar">{initials}</span>{escape(name)}</span></td><td data-label="{escape(w["email"])}"><span class="email-cell">{escape(email)}</span></td><td data-label="{escape(w["role"])}"><span class="badge neutral">{escape(w[role])}</span></td><td data-label="{escape(w["last_seen"])}">{escape(seen)}</td><td data-label="{escape(w["status"])}"><span class="badge{" warn" if state != "active_status" else ""}">{escape(w[state])}</span></td></tr>' for initials, name, email, role, seen, state in people)
        return f'<section class="page-head"><div><p class="eyebrow">{escape(w["users"])}</p><h1>{escape(w["users_title"])}</h1><p class="lede">{escape(w["users_copy"])}</p></div></section><section class="toolbar" aria-label="{escape(w["users"])}"><label class="search"><input type="search" placeholder="{escape(w["search"])}" aria-label="{escape(w["search"])}"></label><div class="tool-actions"><button class="tap" type="button">{escape(w["filter"])}</button><button class="tap primary" type="button">{escape(w["invite"])}</button></div></section><div class="table-wrap"><table><thead><tr><th>{escape(w["person"])}</th><th>{escape(w["email"])}</th><th>{escape(w["role"])}</th><th>{escape(w["last_seen"])}</th><th>{escape(w["status"])}</th></tr></thead><tbody>{rows}</tbody></table></div><p class="empty-note">{len(people)} {escape(w["users"]).lower()}</p>'

    @staticmethod
    def _reports(w: dict[str, str]) -> str:
        rows = (("Weekly operations summary", "14 June 2026 · 08:00", "PDF"), ("Access review digest", "12 June 2026 · 09:30", "CSV"), ("Service reliability brief", "10 June 2026 · 08:00", "PDF"), ("Delivery throughput", "07 June 2026 · 16:15", "XLSX")) if w["brand"] == "Northstar" else (("ملخص العمليات الأسبوعي", "14 يونيو 2026 · 08:00", "PDF"), ("ملخص مراجعة الوصول", "12 يونيو 2026 · 09:30", "CSV"), ("موجز موثوقية الخدمات", "10 يونيو 2026 · 08:00", "PDF"), ("إنتاجية التسليم", "07 يونيو 2026 · 16:15", "XLSX"))
        body = "".join(f'<tr><td data-label="{escape(w["report"])}"><span class="report-name">{escape(name)}</span><span class="subline">{escape(w["ready"])}</span></td><td data-label="{escape(w["generated"])}">{escape(date)}</td><td data-label="{escape(w["format"])}"><span class="badge neutral">{format_}</span></td><td data-label="{escape(w["status"])}"><span class="badge">{escape(w["ready"])}</span></td></tr>' for name, date, format_ in rows)
        return f'<section class="page-head"><div><p class="eyebrow">{escape(w["reports"])}</p><h1>{escape(w["reports_title"])}</h1><p class="lede">{escape(w["reports_copy"])}</p></div><span class="badge">{escape(w["reports_note"])}</span></section><div class="table-wrap"><table><thead><tr><th>{escape(w["report"])}</th><th>{escape(w["generated"])}</th><th>{escape(w["format"])}</th><th>{escape(w["status"])}</th></tr></thead><tbody>{body}</tbody></table></div>'

    @staticmethod
    def _exports(w: dict[str, str]) -> str:
        jobs = (("EX-4821", "User access audit", "Today, 14:08", "Secure mailbox", "complete"), ("EX-4819", "Monthly delivery ledger", "Today, 13:44", "Data room", "processing"), ("EX-4816", "Support escalation log", "Yesterday, 17:12", "Secure mailbox", "queued"), ("EX-4811", "Deployment history", "Yesterday, 11:02", "Data room", "complete"))
        body = "".join(f'<tr><td data-label="{escape(w["job"])}"><span class="report-name">{job}</span></td><td data-label="{escape(w["exports"])}">{escape(name)}</td><td data-label="{escape(w["requested"])}">{escape(date)}</td><td data-label="{escape(w["destination"])}">{escape(destination)}</td><td data-label="{escape(w["state"])}"><span class="badge{" neutral" if state == "complete" else " warn"}">{escape(w[state])}</span></td></tr>' for job, name, date, destination, state in jobs)
        return f'<section class="page-head"><div><p class="eyebrow">{escape(w["exports"])}</p><h1>{escape(w["exports_title"])}</h1><p class="lede">{escape(w["exports_copy"])}</p></div><button class="tap primary" type="button">{escape(w["new"])} {escape(w["exports"])}</button></section><div class="table-wrap"><table><thead><tr><th>{escape(w["job"])}</th><th>{escape(w["exports"])}</th><th>{escape(w["requested"])}</th><th>{escape(w["destination"])}</th><th>{escape(w["state"])}</th></tr></thead><tbody>{body}</tbody></table></div>'
